const WS = '/home/sandbox/workspace';
const dom = new JSDOM('<!doctype html><html><body><div id="root"></div></body></html>', {
  url: 'http://localhost:5180/',
  pretendToBeVisual: true,
});
const { window } = dom;
const g = globalThis;
g.window = window;
g.document = window.document;
g.localStorage = window.localStorage;
g.navigator = window.navigator;
g.HTMLElement = window.HTMLElement;
g.getComputedStyle = window.getComputedStyle.bind(window);
g.IS_REACT_ACT_ENVIRONMENT = true;
window.matchMedia =
  window.matchMedia ||
  (() => ({ matches: false, media: '', addEventListener() {}, removeEventListener() {}, addListener() {}, removeListener() {} }));
g.matchMedia = window.matchMedia;
if (!window.ResizeObserver) window.ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
g.ResizeObserver = window.ResizeObserver;

const vite = await import(`${WS}/node_modules/vite/dist/node/index.js`);
const React = await import(`${WS}/node_modules/react/index.js`);
const ReactDOMClient = await import(`${WS}/node_modules/react-dom/client.js`);
const act = React.act ?? React.default?.act;

const server = await vite.createServer({
  root: WS,
  configFile: `${WS}/vite.config.ts`,
  server: { middlewareMode: true, hmr: false },
  appType: 'custom',
  logLevel: 'error',
});
const { App } = await server.ssrLoadModule('/src/App.tsx');

const container = window.document.getElementById('root');
let root = ReactDOMClient.createRoot(container);
await act(async () => root.render(React.createElement(App)));

const results = [];
const check = (name, cond) => {
  results.push(Boolean(cond));
  console.log(`${cond ? 'PASS' : 'FAIL'} ${name}`);
};
const tick = () => act(async () => { await new Promise((r) => setTimeout(r, 30)); });
const $ = (sel) => window.document.querySelector(sel);
const $$ = (sel) => [...window.document.querySelectorAll(sel)];
const text = () => window.document.body.textContent;
const isDark = () => window.document.body.className.includes('theme_dark');
const click = async (el) => {
  await act(async () => { el.dispatchEvent(new window.MouseEvent('click', { bubbles: true, cancelable: true })); });
  await tick();
};
const setInput = async (el, value) => {
  await act(async () => {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, value);
    el.dispatchEvent(new window.Event('input', { bubbles: true }));
  });
  await tick();
};
const submitForm = async () => {
  await act(async () => { $('form').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true })); });
  await tick();
};
const hashNav = async (hash) => {
  await act(async () => { window.location.hash = hash; });
  await tick();
  await tick();
};

// ---- Home ----
check('home heading rendered', $('h1')?.textContent.includes('Добро пожаловать'));
check('default theme is light (matchMedia=light)', !isDark());

