import { chromium } from 'playwright';

const BASE = 'http://127.0.0.1:5180/';
const errors = [];
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1000, height: 700 }, colorScheme: 'light' });
const page = await ctx.newPage();
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

const check = (name, cond) => console.log(`${cond ? 'PASS' : 'FAIL'} ${name}`);
const bodyBg = () => page.evaluate(() => getComputedStyle(document.body).backgroundColor);
const bodyClass = () => page.evaluate(() => document.body.className);

await page.goto(BASE);
await page.waitForSelector('h1');
check('home heading', (await page.textContent('h1')).includes('Добро пожаловать'));
check('home uses light theme by default (system=light)', (await bodyClass()).includes('theme_dark') === false);
const lightBg = await bodyBg();
console.log('light bg:', lightBg);

// Navigation via header nav
await page.click('nav[aria-label="Основная навигация"] >> text=Задачи');
await page.waitForSelector('h1:has-text("Задачи")');
check('navigated to tasks via nav', page.url().endsWith('#/tasks'));
check('aria-current on active nav item', (await page.getAttribute('nav a[aria-current="page"]', 'href')) === '#/tasks');

// Add tasks (Enter submits form)
await page.fill('input[placeholder="Что нужно сделать?"]', 'Купить молоко');
await page.press('input[placeholder="Что нужно сделать?"]', 'Enter');
await page.fill('input[placeholder="Что нужно сделать?"]', 'Написать отчёт');
await page.click('button[type="submit"]');
await page.waitForSelector('text=Написать отчёт');
check('two tasks added', (await page.locator('text=Купить молоко').count()) === 1 && (await page.locator('text=Написать отчёт').count()) === 1);
check('counter shows 2 left of 2', (await page.textContent('body')).includes('Осталось: 2 из 2'));

// Toggle first task done
await page.click('label:has-text("Купить молоко")');
await page.waitForTimeout(150);
check('counter updates after check', (await page.textContent('body')).includes('Осталось: 1 из 2'));

// Persist across reload
await page.reload();
await page.waitForSelector('text=Написать отчёт');
check('tasks persist after reload', (await page.textContent('body')).includes('Осталось: 1 из 2'));

// Navigate away and back keeps tasks
await page.click('nav >> text=О приложении');
await page.waitForSelector('h1:has-text("О приложении")');
await page.click('nav >> text=Задачи');
await page.waitForSelector('text=Написать отчёт');
check('tasks kept across navigation', (await page.textContent('body')).includes('Осталось: 1 из 2'));

// Browser Back
await page.goBack();
await page.waitForSelector('h1:has-text("О приложении")');
check('browser Back works (tasks -> about)', page.url().endsWith('#/about'));

// Theme toggle
await page.click('nav >> text=Задачи');
await page.waitForSelector('h1:has-text("Задачи")');
await page.click('label:has-text("Тёмная тема")');
await page.waitForTimeout(200);
check('dark class applied on body', (await bodyClass()).includes('theme_dark'));
const darkBg = await bodyBg();
console.log('dark bg:', darkBg);
check('body background changed on dark', darkBg !== lightBg);
check('localStorage app-theme=dark', (await page.evaluate(() => localStorage.getItem('app-theme'))) === 'dark');
await page.screenshot({ path: '/tmp/e2e/tasks-dark.png', fullPage: true });

// Theme persists across reload and navigation
await page.reload();
await page.waitForSelector('h1:has-text("Задачи")');
check('dark theme persists after reload', (await bodyClass()).includes('theme_dark'));
check('switch is checked in dark', await page.isChecked('input[type="checkbox"][role="switch"], label:has-text("Тёмная тема") input'));
await page.click('nav >> text=Главная');
await page.waitForSelector('h1:has-text("Добро пожаловать")');
check('dark persists across nav', (await bodyClass()).includes('theme_dark'));

// Toggle back to light
await page.click('label:has-text("Тёмная тема")');
await page.waitForTimeout(200);
check('light again after toggle', (await bodyClass()).includes('theme_dark') === false && (await bodyBg()) === lightBg);
check('localStorage app-theme=light', (await page.evaluate(() => localStorage.getItem('app-theme'))) === 'light');

// Direct load of about via hash
await page.goto(BASE + '#/about');
await page.waitForSelector('h1:has-text("О приложении")');
check('direct hash load of #/about', true);

// Unknown hash falls back to home
await page.goto(BASE + '#/nope');
await page.waitForSelector('h1:has-text("Добро пожаловать")');
check('unknown hash falls back to home', true);

await page.goto(BASE + '#/tasks');
await page.waitForSelector('h1:has-text("Задачи")');
await page.screenshot({ path: '/tmp/e2e/tasks-light.png', fullPage: true });

console.log('console errors/warnings:', errors.length ? errors : 'none');
await browser.close();
EOF
